-- ============================================================
-- SchoolPulse Analytics Version 2
-- ============================================================

DROP DATABASE IF EXISTS SchoolPulsePortfolio;
CREATE DATABASE SchoolPulsePortfolio
    CHARACTER SET utf8mb4;
USE SchoolPulsePortfolio;

SET NAMES utf8mb4;

CREATE TABLE AcademicYear (
    AcademicYearID VARCHAR(15) PRIMARY KEY,
    YearName VARCHAR(20) NOT NULL,
    StartDate DATE NOT NULL,
    EndDate DATE NOT NULL,
    IsActive VARCHAR(3) NOT NULL,
    CONSTRAINT CheckAcademicYearIsActive CHECK (IsActive IN ('YES', 'NO'))
);

CREATE TABLE Term (
    TermID VARCHAR(15) PRIMARY KEY,
    AcademicYearID VARCHAR(15) NOT NULL,
    TermName VARCHAR(20) NOT NULL,
    StartDate DATE NOT NULL,
    EndDate DATE NOT NULL,
    TermStatus VARCHAR(20) NOT NULL,
    CONSTRAINT ForeignKeyTermAcademicYear FOREIGN KEY (AcademicYearID)
        REFERENCES AcademicYear(AcademicYearID),
    CONSTRAINT CheckTermName CHECK (TermName IN ('First Term', 'Second Term', 'Third Term')),
    CONSTRAINT CheckTermStatus CHECK (TermStatus IN ('Planned', 'Active', 'Completed'))
);

CREATE TABLE ClassLevel (
    ClassLevelID VARCHAR(15) PRIMARY KEY,
    LevelName VARCHAR(20) NOT NULL UNIQUE,
    SchoolSection VARCHAR(30) NOT NULL,
    LevelOrder INT NOT NULL,
    CONSTRAINT CheckSchoolSection CHECK (SchoolSection IN ('Junior Secondary', 'Senior Secondary'))
);

CREATE TABLE AcademicStream (
    StreamID VARCHAR(15) PRIMARY KEY,
    StreamName VARCHAR(30) NOT NULL UNIQUE,
    StreamStatus VARCHAR(20) NOT NULL,
    CONSTRAINT CheckStreamStatus CHECK (StreamStatus IN ('Active', 'Inactive'))
);

CREATE TABLE SchoolClass (
    ClassID VARCHAR(15) PRIMARY KEY,
    ClassLevelID VARCHAR(15) NOT NULL,
    StreamID VARCHAR(15) NULL,
    ClassName VARCHAR(50) NOT NULL UNIQUE,
    Arm VARCHAR(10) NOT NULL,
    ClassSection VARCHAR(20) NOT NULL,
    ClassStatus VARCHAR(20) NOT NULL,
    CONSTRAINT ForeignKeySchoolClassClassLevel FOREIGN KEY (ClassLevelID)
        REFERENCES ClassLevel(ClassLevelID),
    CONSTRAINT ForeignKeySchoolClassStream FOREIGN KEY (StreamID)
        REFERENCES AcademicStream(StreamID),
    CONSTRAINT CheckClassSection CHECK (ClassSection IN ('Junior', 'Senior')),
    CONSTRAINT CheckClassStatus CHECK (ClassStatus IN ('Active', 'Inactive')),
    CONSTRAINT CheckStreamBySection CHECK (
        (ClassSection = 'Junior' AND StreamID IS NULL)
        OR (ClassSection = 'Senior' AND StreamID IS NOT NULL)
    )
);

CREATE TABLE Student (
    StudentID VARCHAR(15) PRIMARY KEY,
    FirstName VARCHAR(50) NOT NULL,
    LastName VARCHAR(50) NOT NULL,
    Gender VARCHAR(10) NOT NULL,
    DateOfBirth DATE NOT NULL,
    AdmissionDate DATE NOT NULL,
    StudentStatus VARCHAR(20) NOT NULL,
    CONSTRAINT CheckStudentGender CHECK (Gender IN ('Male', 'Female')),
    CONSTRAINT CheckStudentStatus CHECK (StudentStatus IN ('Active', 'Inactive', 'Graduated', 'Transferred'))
);

CREATE TABLE Teacher (
    TeacherID VARCHAR(15) PRIMARY KEY,
    FirstName VARCHAR(50) NOT NULL,
    LastName VARCHAR(50) NOT NULL,
    Email VARCHAR(100) NOT NULL UNIQUE,
    Phone VARCHAR(20),
    TeacherStatus VARCHAR(20) NOT NULL,
    CONSTRAINT CheckTeacherStatus CHECK (TeacherStatus IN ('Active', 'Inactive'))
);

CREATE TABLE SchoolSubject (
    SubjectID VARCHAR(15) PRIMARY KEY,
    SubjectName VARCHAR(80) NOT NULL UNIQUE,
    SubjectCategory VARCHAR(30) NOT NULL,
    SubjectStatus VARCHAR(20) NOT NULL,
    CONSTRAINT CheckSubjectCategory CHECK (
        SubjectCategory IN ('Core', 'Junior', 'Senior Shared', 'Science', 'Commercial', 'Arts')
    ),
    CONSTRAINT CheckSubjectStatus CHECK (SubjectStatus IN ('Active', 'Inactive'))
);

CREATE TABLE StudentEnrollment (
    EnrollmentID VARCHAR(15) PRIMARY KEY,
    StudentID VARCHAR(15) NOT NULL,
    ClassID VARCHAR(15) NOT NULL,
    TermID VARCHAR(15) NOT NULL,
    EnrollmentDate DATE NOT NULL,
    EnrollmentStatus VARCHAR(20) NOT NULL,
    CONSTRAINT ForeignKeyEnrollmentStudent FOREIGN KEY (StudentID)
        REFERENCES Student(StudentID),
    CONSTRAINT ForeignKeyEnrollmentClass FOREIGN KEY (ClassID)
        REFERENCES SchoolClass(ClassID),
    CONSTRAINT ForeignKeyEnrollmentTerm FOREIGN KEY (TermID)
        REFERENCES Term(TermID),
    CONSTRAINT CheckEnrollmentStatus CHECK (EnrollmentStatus IN ('Active', 'Inactive', 'Completed')),
    CONSTRAINT UniqueStudentTerm UNIQUE (StudentID, TermID)
);

CREATE TABLE ClassSubject (
    ClassSubjectID VARCHAR(15) PRIMARY KEY,
    ClassID VARCHAR(15) NOT NULL,
    SubjectID VARCHAR(15) NOT NULL,
    TermID VARCHAR(15) NOT NULL,
    IsCompulsory VARCHAR(3) NOT NULL,
    CONSTRAINT ForeignKeyClassSubjectClass FOREIGN KEY (ClassID)
        REFERENCES SchoolClass(ClassID),
    CONSTRAINT ForeignKeyClassSubjectSubject FOREIGN KEY (SubjectID)
        REFERENCES SchoolSubject(SubjectID),
    CONSTRAINT ForeignKeyClassSubjectTerm FOREIGN KEY (TermID)
        REFERENCES Term(TermID),
    CONSTRAINT CheckIsCompulsory CHECK (IsCompulsory IN ('YES', 'NO')),
    CONSTRAINT UniqueClassSubjectTerm UNIQUE (ClassID, SubjectID, TermID)
);

CREATE TABLE TeacherAssignment (
    TeacherAssignmentID VARCHAR(15) PRIMARY KEY,
    TeacherID VARCHAR(15) NOT NULL,
    ClassSubjectID VARCHAR(15) NOT NULL,
    TermID VARCHAR(15) NOT NULL,
    AssignmentStatus VARCHAR(20) NOT NULL,
    CONSTRAINT ForeignKeyAssignmentTeacher FOREIGN KEY (TeacherID)
        REFERENCES Teacher(TeacherID),
    CONSTRAINT ForeignKeyAssignmentClassSubject FOREIGN KEY (ClassSubjectID)
        REFERENCES ClassSubject(ClassSubjectID),
    CONSTRAINT ForeignKeyAssignmentTerm FOREIGN KEY (TermID)
        REFERENCES Term(TermID),
    CONSTRAINT CheckAssignmentStatus CHECK (AssignmentStatus IN ('Active', 'Inactive')),
    CONSTRAINT UniqueTeacherAssignment UNIQUE (TeacherID, ClassSubjectID, TermID)
);

CREATE TABLE AttendanceRecord (
    AttendanceID VARCHAR(15) PRIMARY KEY,
    EnrollmentID VARCHAR(15) NOT NULL,
    AttendanceDate DATE NOT NULL,
    AttendanceStatus VARCHAR(20) NOT NULL,
    Remarks VARCHAR(120),
    CONSTRAINT ForeignKeyAttendanceEnrollment FOREIGN KEY (EnrollmentID)
        REFERENCES StudentEnrollment(EnrollmentID),
    CONSTRAINT CheckAttendanceStatus CHECK (AttendanceStatus IN ('Present', 'Absent', 'Late', 'Excused')),
    CONSTRAINT UniqueAttendancePerDay UNIQUE (EnrollmentID, AttendanceDate)
);

CREATE TABLE AssessmentType (
    AssessmentTypeID VARCHAR(15) PRIMARY KEY,
    TypeName VARCHAR(50) NOT NULL UNIQUE,
    DefaultWeight DECIMAL(5,2) NOT NULL,
    Description VARCHAR(200),
    CONSTRAINT CheckAssessmentWeight CHECK (DefaultWeight >= 0 AND DefaultWeight <= 100)
);

CREATE TABLE Assessment (
    AssessmentID VARCHAR(15) PRIMARY KEY,
    AssessmentTypeID VARCHAR(15) NOT NULL,
    ClassSubjectID VARCHAR(15) NOT NULL,
    AssessmentName VARCHAR(150) NOT NULL,
    MaxScore DECIMAL(6,2) NOT NULL,
    AssessmentDate DATE NOT NULL,
    CONSTRAINT ForeignKeyAssessmentType FOREIGN KEY (AssessmentTypeID)
        REFERENCES AssessmentType(AssessmentTypeID),
    CONSTRAINT ForeignKeyAssessmentClassSubject FOREIGN KEY (ClassSubjectID)
        REFERENCES ClassSubject(ClassSubjectID),
    CONSTRAINT CheckAssessmentMaxScore CHECK (MaxScore > 0),
    CONSTRAINT UniqueClassSubjectAssessmentType UNIQUE (ClassSubjectID, AssessmentTypeID)
);

CREATE TABLE ScoreRecord (
    ScoreID VARCHAR(15) PRIMARY KEY,
    AssessmentID VARCHAR(15) NOT NULL,
    EnrollmentID VARCHAR(15) NOT NULL,
    ScoreObtained DECIMAL(6,2) NOT NULL,
    ScorePercentage DECIMAL(6,2) NOT NULL,
    ScoreStatus VARCHAR(20) NOT NULL,
    CONSTRAINT ForeignKeyScoreAssessment FOREIGN KEY (AssessmentID)
        REFERENCES Assessment(AssessmentID),
    CONSTRAINT ForeignKeyScoreEnrollment FOREIGN KEY (EnrollmentID)
        REFERENCES StudentEnrollment(EnrollmentID),
    CONSTRAINT CheckScoreStatus CHECK (ScoreStatus IN ('Entered', 'Reviewed')),
    CONSTRAINT CheckScorePercentage CHECK (ScorePercentage >= 0 AND ScorePercentage <= 100),
    CONSTRAINT UniqueStudentAssessmentScore UNIQUE (AssessmentID, EnrollmentID)
);

CREATE TABLE StudentMonthlySummary (
    MonthlySummaryID VARCHAR(15) PRIMARY KEY,
    EnrollmentID VARCHAR(15) NOT NULL,
    MonthName VARCHAR(20) NOT NULL,
    AttendancePercentage DECIMAL(6,2) NOT NULL,
    AverageScore DECIMAL(6,2) NOT NULL,
    SubjectsFailed INT NOT NULL,
    PerformanceChange DECIMAL(6,2),
    SummaryStatus VARCHAR(20) NOT NULL,
    CreatedAt TIMESTAMP DEFAULT (NOW()),
    CONSTRAINT ForeignKeySummaryEnrollment FOREIGN KEY (EnrollmentID)
        REFERENCES StudentEnrollment(EnrollmentID),
    CONSTRAINT CheckSummaryMonth CHECK (MonthName IN (
        'January','February','March','April','May','June',
        'July','August','September','October','November','December'
    )),
    CONSTRAINT CheckSummaryAttendance CHECK (AttendancePercentage >= 0 AND AttendancePercentage <= 100),
    CONSTRAINT CheckSummaryAverageScore CHECK (AverageScore >= 0 AND AverageScore <= 100),
    CONSTRAINT CheckSummarySubjectsFailed CHECK (SubjectsFailed >= 0),
    CONSTRAINT CheckSummaryStatus CHECK (SummaryStatus IN ('Draft', 'Calculated', 'Reviewed')),
    CONSTRAINT UniqueMonthlySummary UNIQUE (EnrollmentID, MonthName)
);

CREATE TABLE StudentRiskProfile (
    RiskProfileID VARCHAR(15) PRIMARY KEY,
    MonthlySummaryID VARCHAR(15) NOT NULL,
    RiskLevel VARCHAR(20) NOT NULL,
    RiskScore DECIMAL(6,2) NOT NULL,
    RiskReason TEXT,
    RecommendedAction TEXT,
    CreatedAt TIMESTAMP DEFAULT (NOW()),
    CONSTRAINT ForeignKeyRiskSummary FOREIGN KEY (MonthlySummaryID)
        REFERENCES StudentMonthlySummary(MonthlySummaryID),
    CONSTRAINT CheckRiskLevel CHECK (RiskLevel IN ('Low', 'Medium', 'High')),
    CONSTRAINT CheckRiskScore CHECK (RiskScore >= 0 AND RiskScore <= 100),
    CONSTRAINT UniqueRiskSummary UNIQUE (MonthlySummaryID)
);

CREATE TABLE StudentSubjectRisk (
    SubjectRiskID VARCHAR(15) PRIMARY KEY,
    MonthlySummaryID VARCHAR(15) NOT NULL,
    ClassSubjectID VARCHAR(15) NOT NULL,
    SubjectAverage DECIMAL(6,2) NOT NULL,
    ClassSubjectAverage DECIMAL(6,2) NOT NULL,
    PerformanceGap DECIMAL(6,2) NOT NULL,
    RiskLevel VARCHAR(20) NOT NULL,
    RiskReason TEXT,
    RecommendedAction TEXT,
    CONSTRAINT ForeignKeySubjectRiskSummary FOREIGN KEY (MonthlySummaryID)
        REFERENCES StudentMonthlySummary(MonthlySummaryID),
    CONSTRAINT ForeignKeySubjectRiskClassSubject FOREIGN KEY (ClassSubjectID)
        REFERENCES ClassSubject(ClassSubjectID),
    CONSTRAINT CheckSubjectRiskLevel CHECK (RiskLevel IN ('Low', 'Medium', 'High')),
    CONSTRAINT UniqueStudentSubjectRisk UNIQUE (MonthlySummaryID, ClassSubjectID)
);

CREATE TABLE RecognitionAward (
    AwardID VARCHAR(15) PRIMARY KEY,
    EnrollmentID VARCHAR(15) NOT NULL,
    TermID VARCHAR(15) NOT NULL,
    AwardName VARCHAR(100) NOT NULL,
    AwardCategory VARCHAR(50) NOT NULL,
    AwardRank INT,
    AwardReason TEXT,
    CreatedAt TIMESTAMP DEFAULT (NOW()),
    CONSTRAINT ForeignKeyAwardEnrollment FOREIGN KEY (EnrollmentID)
        REFERENCES StudentEnrollment(EnrollmentID),
    CONSTRAINT ForeignKeyAwardTerm FOREIGN KEY (TermID)
        REFERENCES Term(TermID)
);

CREATE INDEX IndexEnrollmentClass ON StudentEnrollment(ClassID);
CREATE INDEX IndexEnrollmentTerm ON StudentEnrollment(TermID);
CREATE INDEX IndexAttendanceDate ON AttendanceRecord(AttendanceDate);
CREATE INDEX IndexAssessmentDate ON Assessment(AssessmentDate);
CREATE INDEX IndexScoreEnrollment ON ScoreRecord(EnrollmentID);
CREATE INDEX IndexSummaryMonth ON StudentMonthlySummary(MonthName);
CREATE INDEX IndexRiskLevel ON StudentRiskProfile(RiskLevel);
CREATE INDEX IndexSubjectRiskLevel ON StudentSubjectRisk(RiskLevel);

START TRANSACTION;



