-- ============================================================
-- Power BI Analytics Views
-- ============================================================

CREATE VIEW `Student Overview` AS
SELECT
    se.EnrollmentID AS `Enrollment ID`,
    s.StudentID AS `Student ID`,
    CONCAT(s.FirstName, ' ', s.LastName) AS `Student Name`,
    s.Gender AS `Gender`,
    s.DateOfBirth AS `Date Of Birth`,
    s.AdmissionDate AS `Admission Date`,
    s.StudentStatus AS `Student Status`,
    sc.ClassID AS `Class ID`,
    sc.ClassName AS `Class Name`,
    sc.Arm AS `Arm`,
    sc.ClassSection AS `Class Section`,
    cl.ClassLevelID AS `Class Level ID`,
    cl.LevelName AS `Level Name`,
    cl.LevelOrder AS `Level Order`,
    ast.StreamID AS `Stream ID`,
    COALESCE(ast.StreamName, 'Not Applicable') AS `Academic Stream`,
    t.TermID AS `Term ID`,
    t.TermName AS `Term Name`,
    se.EnrollmentStatus AS `Enrollment Status`
FROM StudentEnrollment se
JOIN Student s
    ON se.StudentID = s.StudentID
JOIN SchoolClass sc
    ON se.ClassID = sc.ClassID
JOIN ClassLevel cl
    ON sc.ClassLevelID = cl.ClassLevelID
LEFT JOIN AcademicStream ast
    ON sc.StreamID = ast.StreamID
JOIN Term t
    ON se.TermID = t.TermID;

CREATE VIEW `Monthly Student Performance` AS
SELECT
    sms.MonthlySummaryID AS `Monthly Summary ID`,
    sms.MonthName AS `Month Name`,
    CASE sms.MonthName
        WHEN 'January' THEN 1
        WHEN 'February' THEN 2
        WHEN 'March' THEN 3
        WHEN 'April' THEN 4
        WHEN 'May' THEN 5
        WHEN 'June' THEN 6
        WHEN 'July' THEN 7
        WHEN 'August' THEN 8
        WHEN 'September' THEN 9
        WHEN 'October' THEN 10
        WHEN 'November' THEN 11
        WHEN 'December' THEN 12
    END AS `Month Number`,
    se.EnrollmentID AS `Enrollment ID`,
    s.StudentID AS `Student ID`,
    CONCAT(s.FirstName, ' ', s.LastName) AS `Student Name`,
    s.Gender AS `Gender`,
    sc.ClassID AS `Class ID`,
    sc.ClassName AS `Class Name`,
    cl.LevelName AS `Level Name`,
    COALESCE(ast.StreamName, 'Not Applicable') AS `Academic Stream`,
    sms.AttendancePercentage AS `Attendance Percentage`,
    sms.AverageScore AS `Average Score`,
    sms.SubjectsFailed AS `Subjects Failed`,
    sms.PerformanceChange AS `Performance Change`,
    srp.RiskScore AS `Risk Score`,
    srp.RiskLevel AS `Risk Level`,
    srp.RiskReason AS `Risk Reason`,
    srp.RecommendedAction AS `Recommended Action`
FROM StudentMonthlySummary sms
JOIN StudentEnrollment se
    ON sms.EnrollmentID = se.EnrollmentID
JOIN Student s
    ON se.StudentID = s.StudentID
JOIN SchoolClass sc
    ON se.ClassID = sc.ClassID
JOIN ClassLevel cl
    ON sc.ClassLevelID = cl.ClassLevelID
LEFT JOIN AcademicStream ast
    ON sc.StreamID = ast.StreamID
JOIN StudentRiskProfile srp
    ON sms.MonthlySummaryID = srp.MonthlySummaryID;

CREATE VIEW `Subject Performance` AS
SELECT
    ssr.SubjectRiskID AS `Subject Risk ID`,
    sms.MonthlySummaryID AS `Monthly Summary ID`,
    sms.MonthName AS `Month Name`,
    CASE sms.MonthName
        WHEN 'January' THEN 1
        WHEN 'February' THEN 2
        WHEN 'March' THEN 3
        WHEN 'April' THEN 4
        WHEN 'May' THEN 5
        WHEN 'June' THEN 6
        WHEN 'July' THEN 7
        WHEN 'August' THEN 8
        WHEN 'September' THEN 9
        WHEN 'October' THEN 10
        WHEN 'November' THEN 11
        WHEN 'December' THEN 12
    END AS `Month Number`,
    s.StudentID AS `Student ID`,
    CONCAT(s.FirstName, ' ', s.LastName) AS `Student Name`,
    sc.ClassID AS `Class ID`,
    sc.ClassName AS `Class Name`,
    cl.LevelName AS `Level Name`,
    COALESCE(ast.StreamName, 'Not Applicable') AS `Academic Stream`,
    subj.SubjectID AS `Subject ID`,
    subj.SubjectName AS `Subject Name`,
    subj.SubjectCategory AS `Subject Category`,
    ssr.SubjectAverage AS `Subject Average`,
    ssr.ClassSubjectAverage AS `Class Subject Average`,
    ssr.PerformanceGap AS `Performance Gap`,
    ssr.RiskLevel AS `Risk Level`,
    ssr.RiskReason AS `Risk Reason`,
    ssr.RecommendedAction AS `Recommended Action`
FROM StudentSubjectRisk ssr
JOIN StudentMonthlySummary sms
    ON ssr.MonthlySummaryID = sms.MonthlySummaryID
JOIN StudentEnrollment se
    ON sms.EnrollmentID = se.EnrollmentID
JOIN Student s
    ON se.StudentID = s.StudentID
JOIN SchoolClass sc
    ON se.ClassID = sc.ClassID
JOIN ClassLevel cl
    ON sc.ClassLevelID = cl.ClassLevelID
LEFT JOIN AcademicStream ast
    ON sc.StreamID = ast.StreamID
JOIN ClassSubject cs
    ON ssr.ClassSubjectID = cs.ClassSubjectID
JOIN SchoolSubject subj
    ON cs.SubjectID = subj.SubjectID;

CREATE VIEW `Attendance Analysis` AS
SELECT
    ar.AttendanceID AS `Attendance ID`,
    ar.AttendanceDate AS `Attendance Date`,
    MONTHNAME(ar.AttendanceDate) AS `Month Name`,
    MONTH(ar.AttendanceDate) AS `Month Number`,
    ar.AttendanceStatus AS `Attendance Status`,
    ar.Remarks AS `Remarks`,
    s.StudentID AS `Student ID`,
    CONCAT(s.FirstName, ' ', s.LastName) AS `Student Name`,
    s.Gender AS `Gender`,
    sc.ClassID AS `Class ID`,
    sc.ClassName AS `Class Name`,
    cl.LevelName AS `Level Name`,
    COALESCE(ast.StreamName, 'Not Applicable') AS `Academic Stream`
FROM AttendanceRecord ar
JOIN StudentEnrollment se
    ON ar.EnrollmentID = se.EnrollmentID
JOIN Student s
    ON se.StudentID = s.StudentID
JOIN SchoolClass sc
    ON se.ClassID = sc.ClassID
JOIN ClassLevel cl
    ON sc.ClassLevelID = cl.ClassLevelID
LEFT JOIN AcademicStream ast
    ON sc.StreamID = ast.StreamID;

CREATE VIEW `Assessment Score Analysis` AS
SELECT
    sr.ScoreID AS `Score ID`,
    a.AssessmentID AS `Assessment ID`,
    a.AssessmentName AS `Assessment Name`,
    a.AssessmentDate AS `Assessment Date`,
    atp.TypeName AS `Assessment Type`,
    atp.DefaultWeight AS `Default Weight`,
    sr.ScoreObtained AS `Score Obtained`,
    sr.ScorePercentage AS `Score Percentage`,
    s.StudentID AS `Student ID`,
    CONCAT(s.FirstName, ' ', s.LastName) AS `Student Name`,
    s.Gender AS `Gender`,
    sc.ClassID AS `Class ID`,
    sc.ClassName AS `Class Name`,
    cl.LevelName AS `Level Name`,
    COALESCE(ast.StreamName, 'Not Applicable') AS `Academic Stream`,
    subj.SubjectID AS `Subject ID`,
    subj.SubjectName AS `Subject Name`,
    subj.SubjectCategory AS `Subject Category`
FROM ScoreRecord sr
JOIN Assessment a
    ON sr.AssessmentID = a.AssessmentID
JOIN AssessmentType atp
    ON a.AssessmentTypeID = atp.AssessmentTypeID
JOIN StudentEnrollment se
    ON sr.EnrollmentID = se.EnrollmentID
JOIN Student s
    ON se.StudentID = s.StudentID
JOIN SchoolClass sc
    ON se.ClassID = sc.ClassID
JOIN ClassLevel cl
    ON sc.ClassLevelID = cl.ClassLevelID
LEFT JOIN AcademicStream ast
    ON sc.StreamID = ast.StreamID
JOIN ClassSubject cs
    ON a.ClassSubjectID = cs.ClassSubjectID
JOIN SchoolSubject subj
    ON cs.SubjectID = subj.SubjectID;

CREATE VIEW `Class Risk Summary` AS
SELECT
    sms.MonthName AS `Month Name`,
    CASE sms.MonthName
        WHEN 'January' THEN 1
        WHEN 'February' THEN 2
        WHEN 'March' THEN 3
        WHEN 'April' THEN 4
        WHEN 'May' THEN 5
        WHEN 'June' THEN 6
        WHEN 'July' THEN 7
        WHEN 'August' THEN 8
        WHEN 'September' THEN 9
        WHEN 'October' THEN 10
        WHEN 'November' THEN 11
        WHEN 'December' THEN 12
    END AS `Month Number`,
    sc.ClassID AS `Class ID`,
    sc.ClassName AS `Class Name`,
    cl.LevelName AS `Level Name`,
    COALESCE(ast.StreamName, 'Not Applicable') AS `Academic Stream`,
    COUNT(*) AS `Total Students`,
    ROUND(AVG(sms.AverageScore), 2) AS `Average Academic Score`,
    ROUND(AVG(sms.AttendancePercentage), 2) AS `Average Attendance`,
    SUM(srp.RiskLevel = 'High') AS `High Risk Students`,
    SUM(srp.RiskLevel = 'Medium') AS `Medium Risk Students`,
    SUM(srp.RiskLevel = 'Low') AS `Low Risk Students`,
    SUM(srp.RiskLevel IN ('High', 'Medium')) AS `Students Requiring Attention`,
    SUM(sms.SubjectsFailed > 0) AS `Students Failing Subjects`
FROM StudentMonthlySummary sms
JOIN StudentRiskProfile srp
    ON sms.MonthlySummaryID = srp.MonthlySummaryID
JOIN StudentEnrollment se
    ON sms.EnrollmentID = se.EnrollmentID
JOIN SchoolClass sc
    ON se.ClassID = sc.ClassID
JOIN ClassLevel cl
    ON sc.ClassLevelID = cl.ClassLevelID
LEFT JOIN AcademicStream ast
    ON sc.StreamID = ast.StreamID
GROUP BY
    sms.MonthName,
    `Month Number`,
    sc.ClassID,
    sc.ClassName,
    cl.LevelName,
    ast.StreamName;

CREATE VIEW `Subject Monthly Summary` AS
SELECT
    sms.MonthName AS `Month Name`,
    CASE sms.MonthName
        WHEN 'January' THEN 1
        WHEN 'February' THEN 2
        WHEN 'March' THEN 3
        WHEN 'April' THEN 4
        WHEN 'May' THEN 5
        WHEN 'June' THEN 6
        WHEN 'July' THEN 7
        WHEN 'August' THEN 8
        WHEN 'September' THEN 9
        WHEN 'October' THEN 10
        WHEN 'November' THEN 11
        WHEN 'December' THEN 12
    END AS `Month Number`,
    sc.ClassID AS `Class ID`,
    sc.ClassName AS `Class Name`,
    cl.LevelName AS `Level Name`,
    COALESCE(ast.StreamName, 'Not Applicable') AS `Academic Stream`,
    subj.SubjectID AS `Subject ID`,
    subj.SubjectName AS `Subject Name`,
    subj.SubjectCategory AS `Subject Category`,
    COUNT(*) AS `Student Subject Records`,
    ROUND(AVG(ssr.SubjectAverage), 2) AS `Average Subject Score`,
    ROUND(AVG(ssr.PerformanceGap), 2) AS `Average Performance Gap`,
    SUM(ssr.RiskLevel = 'High') AS `High Subject Risk Count`,
    SUM(ssr.RiskLevel = 'Medium') AS `Medium Subject Risk Count`,
    SUM(ssr.RiskLevel = 'Low') AS `Low Subject Risk Count`
FROM StudentSubjectRisk ssr
JOIN StudentMonthlySummary sms
    ON ssr.MonthlySummaryID = sms.MonthlySummaryID
JOIN StudentEnrollment se
    ON sms.EnrollmentID = se.EnrollmentID
JOIN SchoolClass sc
    ON se.ClassID = sc.ClassID
JOIN ClassLevel cl
    ON sc.ClassLevelID = cl.ClassLevelID
LEFT JOIN AcademicStream ast
    ON sc.StreamID = ast.StreamID
JOIN ClassSubject cs
    ON ssr.ClassSubjectID = cs.ClassSubjectID
JOIN SchoolSubject subj
    ON cs.SubjectID = subj.SubjectID
GROUP BY
    sms.MonthName,
    `Month Number`,
    sc.ClassID,
    sc.ClassName,
    cl.LevelName,
    ast.StreamName,
    subj.SubjectID,
    subj.SubjectName,
    subj.SubjectCategory;

CREATE VIEW `Student Intervention Queue` AS
SELECT *
FROM `Monthly Student Performance`
WHERE `Risk Level` IN ('High', 'Medium');

-- ============================================================
-- Validation And Portfolio Checks
-- ============================================================

SELECT
    `Check Name`,
    `Actual Value`,
    `Expected Value`,
    CASE
        WHEN `Actual Value` = `Expected Value` THEN 'PASS'
        ELSE 'CHECK'
    END AS `Validation Status`
FROM (
    SELECT
        'Students' AS `Check Name`,
        (SELECT COUNT(*) FROM Student) AS `Actual Value`,
        216 AS `Expected Value`

    UNION ALL

    SELECT
        'Active Enrollments',
        (
            SELECT COUNT(*)
            FROM StudentEnrollment
            WHERE EnrollmentStatus = 'Active'
        ),
        216

    UNION ALL

    SELECT 'Classes', (SELECT COUNT(*) FROM SchoolClass), 18

    UNION ALL

    SELECT 'Subjects', (SELECT COUNT(*) FROM SchoolSubject), 35

    UNION ALL

    SELECT 'Teachers', (SELECT COUNT(*) FROM Teacher), 45

    UNION ALL

    SELECT
        'Class Subject Assignments',
        (SELECT COUNT(*) FROM ClassSubject),
        236

    UNION ALL

    SELECT
        'Teacher Assignments',
        (SELECT COUNT(*) FROM TeacherAssignment),
        236

    UNION ALL

    SELECT 'Assessments', (SELECT COUNT(*) FROM Assessment), 944

    UNION ALL

    SELECT 'Score Records', (SELECT COUNT(*) FROM ScoreRecord), 11328

    UNION ALL

    SELECT
        'Attendance Records',
        (SELECT COUNT(*) FROM AttendanceRecord),
        13608

    UNION ALL

    SELECT
        'Monthly Summaries',
        (SELECT COUNT(*) FROM StudentMonthlySummary),
        864

    UNION ALL

    SELECT
        'Overall Risk Profiles',
        (SELECT COUNT(*) FROM StudentRiskProfile),
        864

    UNION ALL

    SELECT
        'Subject Risk Records',
        (SELECT COUNT(*) FROM StudentSubjectRisk),
        11328

    UNION ALL

    SELECT
        'Recognition Awards',
        (SELECT COUNT(*) FROM RecognitionAward),
        54

    UNION ALL

    SELECT
        'Duplicate Attendance Records',
        (
            SELECT COUNT(*)
            FROM (
                SELECT
                    EnrollmentID,
                    AttendanceDate
                FROM AttendanceRecord
                GROUP BY
                    EnrollmentID,
                    AttendanceDate
                HAVING COUNT(*) > 1
            ) DuplicateAttendance
        ),
        0

    UNION ALL

    SELECT
        'Duplicate Score Records',
        (
            SELECT COUNT(*)
            FROM (
                SELECT
                    AssessmentID,
                    EnrollmentID
                FROM ScoreRecord
                GROUP BY
                    AssessmentID,
                    EnrollmentID
                HAVING COUNT(*) > 1
            ) DuplicateScores
        ),
        0

    UNION ALL

    SELECT
        'Monthly Summaries Without Risk Profile',
        (
            SELECT COUNT(*)
            FROM StudentMonthlySummary sms
            LEFT JOIN StudentRiskProfile srp
                ON sms.MonthlySummaryID = srp.MonthlySummaryID
            WHERE srp.RiskProfileID IS NULL
        ),
        0
) ValidationChecks
ORDER BY `Check Name`;

SELECT
    cl.LevelName AS `Level Name`,
    COALESCE(ast.StreamName, 'Not Applicable') AS `Academic Stream`,
    sc.ClassName AS `Class Name`,
    COUNT(cs.ClassSubjectID) AS `Assigned Subjects`
FROM SchoolClass sc
JOIN ClassLevel cl
    ON sc.ClassLevelID = cl.ClassLevelID
LEFT JOIN AcademicStream ast
    ON sc.StreamID = ast.StreamID
JOIN ClassSubject cs
    ON sc.ClassID = cs.ClassID
GROUP BY
    cl.LevelName,
    ast.StreamName,
    sc.ClassName
ORDER BY
    cl.LevelOrder,
    sc.ClassName;

SELECT
    `Month Name`,
    COUNT(*) AS `Students`,
    ROUND(AVG(`Average Score`), 2) AS `Average Academic Score`,
    ROUND(AVG(`Attendance Percentage`), 2) AS `Average Attendance`,
    SUM(`Risk Level` = 'High') AS `High Risk`,
    SUM(`Risk Level` = 'Medium') AS `Medium Risk`,
    SUM(`Risk Level` = 'Low') AS `Low Risk`
FROM `Monthly Student Performance`
GROUP BY
    `Month Name`,
    `Month Number`
ORDER BY `Month Number`;

SELECT
    `Academic Stream`,
    COUNT(DISTINCT `Student ID`) AS `Students`,
    ROUND(AVG(`Average Score`), 2) AS `Average Score`,
    ROUND(AVG(`Attendance Percentage`), 2) AS `Average Attendance`
FROM `Monthly Student Performance`
WHERE `Month Name` = 'April'
GROUP BY `Academic Stream`
ORDER BY `Academic Stream`;

